    switch (event.key) {
      case 'ArrowDown':
        event.preventDefault()
        setActiveIndex((index) => Math.min(index + 1, results.length - 1))
        break
      case 'ArrowUp':
        event.preventDefault()
        setActiveIndex((index) => Math.max(index - 1, 0))
        break
      case 'Enter': {
        event.preventDefault()
        const city = results[activeIndex]
        if (city) select(city)
        break
      }
      case 'Escape':
        event.preventDefault()
        close()
        break
    }
