      </button>

      {open && (
        <div
          className="absolute left-0 z-30 mt-2 w-[min(22rem,calc(100vw-2rem))] animate-fade-up overflow-hidden rounded-2xl border border-ink-700 bg-ink-850 shadow-2xl shadow-black/60"
